		THEN(
            IF(isExistPreDataNode, THEN(
                loadPreDataNode,
                WHEN(
                    loadStaticDataNode,
                    loadRuleDataNode.tag("pre")
                ),
                IF(isExistRuleDataNode, THEN(
                    generateRuleEventsNode,
                    runRuleNode,
                    preProcessExceptionNode
                )),
                savePreDataNode,
                modifyMetaDataAnalysisStatusNode,
                notificationNode.tag("callModel")
            ))
        );





        THEN(
            IF(isExistCallModelDataNode, THEN(
                loadCallModelDataNode,
                CATCH(
                   THEN(
                      callModelApiServiceNode,
                      analysisModelResultDataNode
                       )
                ).DO(exceptionModelDataNode),
                WHEN(
                  saveModelNotLabelDataNode,
                  saveHighFrequencyWordsNode,
                  modifyToMetaDataAnalysisStatusNode
                 ),
                IF(isExistLabelDataNode, THEN(
                    saveModelLabelDataNode,
                    saveModelLabelExtDataNode,
                   notificationNode.tag("postRules")
                ))

            ))
        );




        THEN(
            IF(isExistCallModelDataNode, THEN(
               loadCallModelDataNode,
               callModelMqPushServiceNode
            ))
        );

·


        THEN(
            callModelMqReceiveServiceNode,
            analysisModelResultDataNode,
        WHEN(
            saveModelNotLabelDataNode,
            saveModelLabelDataNode,
            saveModelLabelExtDataNode,
            modifyToMetaDataAnalysisStatusNode
           )
        );



        THEN(
            ITERATOR(isExistModelResultDataNode).DO(        
                THEN(


                    moveModelResultDataToFinalTableNode
                )
            )
        );





        THEN(
            IF(isExistPostDataNode, THEN(
                loadPostDataNode,
                WHEN(
                    loadStaticDataNode,
                    loadRuleDataNode.tag("post")
                ),
                IF(isExistRuleDataNode, THEN(
                    generateRuleEventsNode,
                    runRuleNode,
                    postProcessExceptionNode
                )),
                savePostDataNode,
                modifyModelResltDataAnalysisStatusNode
            ))
        );





        THEN(
            IF(isSplitValidDataWhileNode, THEN(
                WHEN(
                    loadStaticDataNode.tag("valid"),
                    loadValidRuleDataNode.tag("post")
                ),
                IF(isExistRuleDataNode, THEN(
                    generateRuleEventsNode,
                    runRuleNode
                )),
                saveValidPostDataNode,
                modifyModelResltDataAnalysisValidStatusNode
            ))
        );




		THEN(
			THEN(
				WHEN(
					loadStaticDataNode,
					loadRuleDataNode.tag("pre")
				),
				IF(isExistRuleDataNode, THEN(
					generateRuleEventsNode,
					runRuleNode
				))
			),
			THEN(
                callModelApiServiceNode,
                modelResultAnalysisDataNode
			),
			THEN(
				WHEN(
					loadStaticDataNode,
					loadRuleDataNode.tag("post")
				),
				IF(isExistRuleDataNode, THEN(
					generateRuleEventsNode
//					runRuleNodeAnalysisServiceNode
				))
			)
		);
